def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    op = [h[1] for h in history]
    my = [h[0] for h in history]
    opD = op.count('D')
    opC = n - opD
    myD = my.count('D')

    # Perfectly cooperative so far: cooperate, but defect on the very last round.
    if opD == 0:
        if n >= 100:
            return 'D'
        return 'C'

    # Opponent always defects: defect, but occasionally forgive to test for change.
    if opC == 0:
        if n < 100 and n >= 3 and rng.random() < 0.05:
            return 'C'
        return 'D'

    # Near end: exploit, but only if opponent isn't clearly punishing.
    remaining = 100 - n
    if remaining <= 1:
        return 'D'
    if remaining <= 3:
        if op[-1] == 'C' and op[-2] == 'C':
            return 'D'
        return 'D'

    # Sustained defection detection.
    if n >= 20 and opD * 4 >= n * 3:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # If last opponent action was D: retaliate with high probability.
    if op[-1] == 'D':
        # Count recent opponent defections.
        recent = op[-6:]
        rd = recent.count('D')
        if rd >= 3:
            if rng.random() < 0.03:
                return 'C'
            return 'D'
        # Single defection: retaliate but be forgiving.
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Opponent just cooperated. Decide whether to cooperate or exploit.
    # If opponent has been very cooperative, mostly cooperate but occasionally probe.
    if opC * 10 >= n * 9:
        if n >= 10 and (n % 11 == 0):
            return 'D'
        return 'C'

    # If opponent cooperation moderate, use a generious tit-for-tat style.
    recent = op[-5:]
    rd = recent.count('D')
    if rd == 0:
        return 'C'
    if rd == 1:
        # Mostly cooperate, small chance to exploit
        if rng.random() < 0.1:
            return 'D'
        return 'C'
    if rd >= 2:
        # Opponent defecting somewhat recently: retaliate but offer olive branch.
        if rng.random() < 0.6:
            return 'D'
        return 'C'
